import test from 'node:test';
import assert from 'node:assert/strict';
import {selectRecords} from '../src/select.js';
const rows=[{id:'b',tenantId:'t1'},{id:'a',tenantId:'t1'},{id:'a',tenantId:'t2'}];
test('only selected tenant records',()=>assert.deepEqual(selectRecords(rows,'t1',['a']),[rows[1]]));
test('empty',()=>assert.deepEqual(selectRecords(rows,'t1',[]),[]));
test('stable order',()=>assert.deepEqual(selectRecords(rows,'t1',['a','b']),rows.slice(0,2)));
test('immutable',()=>{const a=structuredClone(rows),ids=['b','a'];selectRecords(a,'t1',ids);assert.deepEqual(a,rows);assert.deepEqual(ids,['b','a']);});

