import test, {afterEach} from 'node:test';
import assert from 'node:assert/strict';
import {existsSync,mkdirSync,mkdtempSync,readdirSync,rmSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
const root=fileURLToPath(new URL('../.scratch/',import.meta.url));
mkdirSync(root,{recursive:true});
afterEach(()=>assert.deepEqual(readdirSync(root),[],'resource directories must be released'));
test('temporary resource is isolated',()=>{
  const resource=mkdtempSync(path.join(root,'resource-'));
  assert.equal(existsSync(resource),true);
});

